/**
 * Bestiary names belonging to an activity represented on the official OSRS boss Hiscores.
 * Component bosses use their in-game Bestiary name so filtering and permits remain exact.
 */
final class BossRegistry
{
	private static final Set<String> BOSSES = names(
		"Abyssal Sire", "Alchemical Hydra", "Amoxliatl", "Araxxor", "Artio",
		"Ahrim the Blighted", "Dharok the Wretched", "Guthan the Infested",
		"Karil the Tainted", "Torag the Corrupted", "Verac the Defiled",
		"Brutus", "Bryophyta", "Callisto", "Calvar'ion", "Cerberus",
		SpecialEncounterRules.CHAMBERS_OF_XERIC,
		"Chaos Elemental", "Chaos Fanatic", "Commander Zilyana", "Corporeal Beast",
		"Crazy archaeologist", "Dagannoth Prime", "Dagannoth Rex", "Dagannoth Supreme",
		"Deranged archaeologist", "Doom of Mokhaiotl",
		"Duke Sucellus", "General Graardor", "Giant Mole", "Dawn", "Dusk",
		"Hespori", "Kalphite Queen", "King Black Dragon", "Kraken", "Kree'arra",
		"K'ril Tsutsaroth", "Mad Angel", "Maggot King", "The Mimic", "Nex",
		"The Nightmare", "Phosani's Nightmare",
		"Obor", "Phantom Muspah", "Sarachnis", "Scorpia", "Scurrius",
		"Shellbane Gryphon", "Skotizo",
		"Sol Heredit", "Spindel", "Tempoross", "Crystalline Hunllef",
		"Corrupted Hunllef", "The Hueycoatl", "The Leviathan", "The Whisperer",
		"Blood Moon", "Blue Moon", "Eclipse Moon",
		"Branda, Queen of Fire", "Eldric, King of Ice",
		SpecialEncounterRules.THEATRE_OF_BLOOD,
		"Thermonuclear smoke devil", SpecialEncounterRules.TOMBS_OF_AMASCUT,
		"TzKal-Zuk", "TzTok-Jad", "Vardorvis", "Venenatis", "Vet'ion", "Vorkath",
		"Wintertodt", "Yama", "Zalcano", "Zulrah"
	);

	private BossRegistry() {}

	static boolean isBoss(String name)
	{
		return name != null && BOSSES.contains(name);
	}

	static Set<String> names()
	{
		return BOSSES;
	}

	private static Set<String> names(String... values)
	{
		Set<String> result = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		result.addAll(Arrays.asList(values));
		return Collections.unmodifiableSet(result);
	}
}

package com.extinctionman;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;

final class CollectionLogPopupRenderer
{
	static final Color ORANGE = new Color(255, 152, 31);
	static final Color WHITE = new Color(238, 238, 238);
	static final Color SOUL_BLUE = new Color(170, 225, 255);
	static final Font HEADER_FONT = new Font(Font.SERIF, Font.BOLD, 20);
	static final Font MAIN_FONT = new Font(Font.SERIF, Font.BOLD, 18);
	static final Font DETAIL_FONT = new Font(Font.SERIF, Font.BOLD, 13);
	private static final Color STONE_DARK = new Color(43, 42, 35, 250);
	private static final Color STONE = new Color(100, 96, 79, 250);
	private static final Color STONE_LIGHT = new Color(153, 145, 116, 250);
	private static final Color PANEL = new Color(55, 47, 37, 250);
	private static final Color PANEL_EDGE = new Color(25, 24, 21, 250);

	private CollectionLogPopupRenderer() {}

	static void drawFrame(Graphics2D graphics, int x, int y, int width, int height, String header)
	{
		graphics.setColor(STONE_DARK);
		graphics.fillRect(x, y, width, height);
		graphics.setColor(STONE);
		graphics.fillRect(x + 3, y + 3, width - 6, height - 6);
		graphics.setColor(STONE_LIGHT);
		graphics.drawRect(x + 4, y + 4, width - 9, height - 9);
		graphics.setColor(PANEL_EDGE);
		graphics.fillRect(x + 11, y + 11, width - 22, height - 22);
		graphics.setColor(PANEL);
		graphics.fillRect(x + 15, y + 15, width - 30, height - 30);

		int dividerY = y + 45;
		graphics.setColor(PANEL_EDGE);
		graphics.fillRect(x + 12, dividerY, width - 24, 5);
		graphics.setColor(STONE_LIGHT.darker());
		graphics.drawLine(x + 15, dividerY - 1, x + width - 16, dividerY - 1);

		drawCorner(graphics, x + 4, y + 4, 1, 1);
		drawCorner(graphics, x + width - 5, y + 4, -1, 1);
		drawCorner(graphics, x + 4, y + height - 5, 1, -1);
		drawCorner(graphics, x + width - 5, y + height - 5, -1, -1);
		drawCentered(graphics, header, x, width, y + 35, HEADER_FONT, ORANGE);
	}

	static void drawCentered(Graphics2D graphics, String text, int x, int width, int baseline,
		Font font, Color color)
	{
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();
		int textX = x + (width - metrics.stringWidth(text)) / 2;
		graphics.setColor(new Color(0, 0, 0, 210));
		graphics.drawString(text, textX + 2, baseline + 2);
		graphics.setColor(color);
		graphics.drawString(text, textX, baseline);
	}

	private static void drawCorner(Graphics2D graphics, int x, int y, int horizontal, int vertical)
	{
		graphics.setStroke(new BasicStroke(2));
		graphics.setColor(STONE_LIGHT);
		graphics.drawLine(x, y + 8 * vertical, x + 8 * horizontal, y);
		graphics.setColor(STONE_DARK);
		graphics.drawLine(x + 3 * horizontal, y + 10 * vertical, x + 10 * horizontal, y + 3 * vertical);
		graphics.setStroke(new BasicStroke(1));
	}
}

package com.extinctionman;

import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import javax.inject.Singleton;
import net.runelite.api.NPC;

/** Allows all loot from the kill which first completed an extinction. */
@Singleton
final class CompletionLootAllowance
{
	private final Set<NPC> allowed = Collections.newSetFromMap(new IdentityHashMap<>());

	void mark(NPC npc)
	{
		if (npc != null) allowed.add(npc);
	}

	boolean consume(NPC npc)
	{
		return npc != null && allowed.remove(npc);
	}

	void forget(NPC npc) { allowed.remove(npc); }
	void clear() { allowed.clear(); }
}

package com.extinctionman;

final class CompletionRewardAllowance
{
	private String pendingSource;
	private String activeSource;

	void allow(String source, String openRewardSource)
	{
		if (source != null && source.equals(openRewardSource))
		{
			activeSource = source;
			pendingSource = null;
		}
		else
		{
			pendingSource = source;
		}
	}

	void claim(String source)
	{
		if (source != null && source.equals(pendingSource))
		{
			activeSource = source;
			pendingSource = null;
		}
	}

	boolean allows(String source)
	{
		return source != null && (source.equals(pendingSource) || source.equals(activeSource));
	}

	void close(String source)
	{
		if (source != null && source.equals(activeSource)) activeSource = null;
	}

	void clear()
	{
		pendingSource = null;
		activeSource = null;
	}
}

package com.extinctionman;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Singleton;

/** Correlates server-confirmed NPC loot with a matching inventory increase or ground spawn. */
@Singleton
final class DirectSoulLootTracker
{
	private final Map<Integer, Observation> observations = new HashMap<>();
	private final Map<Integer, GroundObservation> recentGround = new HashMap<>();

	void observe(String source, int itemId, int currentTick)
	{
		GroundObservation ground = recentGround.get(itemId);
		boolean groundObserved = ground != null && source.equals(ground.sourceName)
			&& currentTick - ground.tick >= 0 && currentTick - ground.tick <= 1;
		observations.put(itemId, new Observation(source, currentTick, groundObserved));
	}

	void markGround(String source, int itemId, int currentTick)
	{
		recentGround.put(itemId, new GroundObservation(source, currentTick));
		Observation observation = observations.get(itemId);
		if (observation != null && source.equals(observation.sourceName))
		{
			observation.groundObserved = true;
		}
	}

	String claimInventoryIncrease(int itemId, int currentTick)
	{
		Observation observation = observations.get(itemId);
		if (observation == null || observation.groundObserved
			|| currentTick < observation.observedAtTick
			|| currentTick > observation.observedAtTick + 2) return null;
		observations.remove(itemId);
		return observation.sourceName;
	}

	void expire(int currentTick)
	{
		observations.entrySet().removeIf(entry -> currentTick > entry.getValue().observedAtTick + 2);
		recentGround.entrySet().removeIf(entry -> currentTick > entry.getValue().tick + 2);
	}

	void clear()
	{
		observations.clear();
		recentGround.clear();
	}

	private static final class Observation
	{
		private final String sourceName;
		private final int observedAtTick;
		private boolean groundObserved;
		private Observation(String sourceName, int observedAtTick, boolean groundObserved)
		{
			this.sourceName = sourceName;
			this.observedAtTick = observedAtTick;
			this.groundObserved = groundObserved;
		}
	}

	private static final class GroundObservation
	{
		private final String sourceName;
		private final int tick;
		private GroundObservation(String sourceName, int tick)
		{
			this.sourceName = sourceName;
			this.tick = tick;
		}
	}
}

package com.extinctionman;

import javax.inject.Singleton;

@Singleton
final class ExterminationWaveTracker
{
	static final int DURATION_TICKS = 6;
	private String npcName;
	private int animationExpiresAtTick;

	void start(String exactNpcName, int currentTick)
	{
		npcName = exactNpcName;
		animationExpiresAtTick = currentTick + DURATION_TICKS;
	}

	boolean isAnimating(String exactNpcName, int currentTick)
	{
		clearIfFinished(currentTick);
		return npcName != null
			&& currentTick < animationExpiresAtTick
			&& npcName.equals(exactNpcName);
	}

	boolean isActive(String exactNpcName, int currentTick)
	{
		clearIfFinished(currentTick);
		return npcName != null && npcName.equals(exactNpcName);
	}

	private void clearIfFinished(int currentTick)
	{
		if (npcName != null && currentTick >= animationExpiresAtTick)
		{
			clear();
		}
	}

	void clear()
	{
		npcName = null;
		animationExpiresAtTick = 0;
	}
}

package com.extinctionman;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class ExtinctGhostOverlay extends Overlay
{
	private static final long ANIMATION_MILLIS = 1800L;
	private final Client client;
	private final ExtinctGhostTracker tracker;

	@Inject
	ExtinctGhostOverlay(Client client, ExtinctGhostTracker tracker)
	{
		this.client = client;
		this.tracker = tracker;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		long now = System.currentTimeMillis();
		for (NPC npc : tracker.active())
		{
			LocalPoint localPoint = npc.getLocalLocation();
			if (localPoint == null)
			{
				continue;
			}

			int height = Math.max(45, npc.getLogicalHeight() / 2);
			Point center = Perspective.localToCanvas(client, localPoint, npc.getWorldLocation().getPlane(), height);
			if (center == null)
			{
				continue;
			}

			double phase = ((now + npc.getIndex() * 137L) % ANIMATION_MILLIS)
				/ (double) ANIMATION_MILLIS;
			SoulOrbRenderer.drawException(graphics, center.getX(), center.getY(), phase,
				tracker.getType(npc));
		}
		return null;
	}
}

package com.extinctionman;

import java.util.Collection;
import java.util.Collections;
import java.util.Map;
import java.util.IdentityHashMap;
import javax.inject.Singleton;
import net.runelite.api.NPC;

@Singleton
final class ExtinctGhostTracker
{
	// Accessed on the client/render thread. NPC identity must survive index reuse.
	private final Map<NPC, SoulExceptionType> ghosts = new IdentityHashMap<>();
	private final Collection<NPC> view = Collections.unmodifiableSet(ghosts.keySet());

	void replace(Map<NPC, SoulExceptionType> npcs)
	{
		ghosts.clear();
		ghosts.putAll(npcs);
	}

	Collection<NPC> active()
	{
		return view;
	}

	void update(NPC npc, boolean ghost)
	{
		update(npc, ghost, SoulExceptionType.UNBOUND);
	}

	void update(NPC npc, boolean ghost, boolean golden)
	{
		update(npc, ghost, golden ? SoulExceptionType.UNBOUND : SoulExceptionType.SLAYER);
	}

	void update(NPC npc, boolean ghost, SoulExceptionType type)
	{
		if (ghost) ghosts.put(npc, type);
		else ghosts.remove(npc);
	}

	boolean isGolden(NPC npc)
	{
		return ghosts.get(npc) == SoulExceptionType.UNBOUND;
	}

	SoulExceptionType getType(NPC npc)
	{
		return ghosts.get(npc);
	}

	boolean contains(NPC npc)
	{
		return ghosts.containsKey(npc);
	}

	void remove(NPC npc)
	{
		ghosts.remove(npc);
	}

	void clear()
	{
		ghosts.clear();
	}
}

package com.extinctionman;

final class ExtinctionCelebration
{
	private final String npcName;
	private final long startedAtMillis;
	private final boolean soulPointAwarded;
	private final String completionText;
	private boolean soundClaimed;

	ExtinctionCelebration(String npcName, long startedAtMillis, boolean soulPointAwarded)
	{
		this(npcName, startedAtMillis, soulPointAwarded,
			(BossRegistry.isBoss(npcName) ? "10" : "1") + " Soul Energy Collected");
	}

	ExtinctionCelebration(String npcName, long startedAtMillis, boolean soulPointAwarded,
		String completionText)
	{
		this.npcName = npcName;
		this.startedAtMillis = startedAtMillis;
		this.soulPointAwarded = soulPointAwarded;
		this.completionText = completionText;
	}

	boolean isSoulPointAwarded()
	{
		return soulPointAwarded;
	}

	String getNpcName()
	{
		return npcName;
	}

	String getCompletionText() { return completionText; }

	boolean claimSound()
	{
		if (soundClaimed) return false;
		soundClaimed = true;
		return true;
	}

	float alpha(long nowMillis, long durationMillis)
	{
		return PopupAnimation.alpha(nowMillis, startedAtMillis, durationMillis);
	}

	float unfold(long nowMillis, long durationMillis)
	{
		return PopupAnimation.unfold(nowMillis, startedAtMillis, durationMillis);
	}

	boolean isFinished(long nowMillis, long durationMillis)
	{
		return nowMillis - startedAtMillis >= durationMillis;
	}
}

package com.extinctionman;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class ExtinctionCelebrationOverlay extends Overlay
{
	private final ExtinctionManConfig config;
	private final ExtinctionCelebrationTracker tracker;

	@Inject
	ExtinctionCelebrationOverlay(ExtinctionManConfig config, ExtinctionCelebrationTracker tracker)
	{
		this.config = config;
		this.tracker = tracker;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showExtinctionPopup()) return null;
		long now = System.currentTimeMillis();
		ExtinctionCelebration celebration = tracker.active(now);
		if (celebration == null) return null;
		ThemedPopupRenderer.draw(graphics,
			celebration.unfold(now, ExtinctionCelebrationTracker.DURATION_MILLIS), now,
			"Exterminated", celebration.getNpcName(), CollectionLogPopupRenderer.WHITE,
			celebration.getCompletionText(), CollectionLogPopupRenderer.SOUL_BLUE, false);
		return null;
	}
}

package com.extinctionman;

import javax.inject.Singleton;

@Singleton
final class ExtinctionCelebrationTracker
{
	static final long DURATION_MILLIS = 7000;
	private ExtinctionCelebration celebration;

	void show(String npcName, long nowMillis, boolean soulPointAwarded)
	{
		celebration = new ExtinctionCelebration(npcName, nowMillis, soulPointAwarded);
	}

	void showRaid(String raidName, long nowMillis, boolean soulPointAwarded)
	{
		celebration = new ExtinctionCelebration(
			raidName, nowMillis, soulPointAwarded,
			(BossRegistry.isBoss(raidName) ? "10" : "1") + " Soul Energy Collected");
	}

	void preview(String npcName, long nowMillis)
	{
		celebration = new ExtinctionCelebration(npcName, nowMillis, false);
	}

	ExtinctionCelebration active(long nowMillis)
	{
		if (celebration != null && celebration.isFinished(nowMillis, DURATION_MILLIS))
		{
			celebration = null;
		}
		return celebration;
	}

	void clear()
	{
		celebration = null;
	}
}

package com.extinctionman;

import java.util.Locale;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;

final class ExtinctionChatMessage
{
	private static final String COLOR = "b84a4a";
	private static final Map<String, String> IRREGULAR_PLURALS = irregularPlurals();

	private ExtinctionChatMessage() {}

	static String random(String npcName)
	{
		return "<col=" + COLOR + ">" + forStyle(npcName,
			ThreadLocalRandom.current().nextInt(3)) + "</col>";
	}

	static String forStyle(String npcName, int style)
	{
		String exactName = npcName == null ? "Unknown creature" : npcName.trim();
		if (usesIndividualWording(exactName))
		{
			return individualMessage(exactName, style);
		}
		String species = exactName.toLowerCase(Locale.ENGLISH);
		String plural = pluralize(species);
		switch (Math.floorMod(style, 3))
		{
			case 0:
				return "The last " + species + " has been slain. "
					+ capitalize(plural) + " are now extinct.";
			case 1:
				return "You just killed the very last " + species
					+ ". The species is gone forever.";
			default:
				return "With that final blow, you have driven " + plural + " to extinction.";
		}
	}

	private static String pluralize(String species)
	{
		int separator = species.lastIndexOf(' ');
		String prefix = separator < 0 ? "" : species.substring(0, separator + 1);
		String finalWord = separator < 0 ? species : species.substring(separator + 1);
		String irregular = IRREGULAR_PLURALS.get(finalWord);
		if (irregular != null) return prefix + irregular;
		if (species.endsWith("ch") || species.endsWith("sh") || species.endsWith("s")
			|| species.endsWith("x") || species.endsWith("z"))
		{
			return species + "es";
		}
		if (species.endsWith("y") && species.length() > 1
			&& "aeiou".indexOf(species.charAt(species.length() - 2)) < 0)
		{
			return species.substring(0, species.length() - 1) + "ies";
		}
		return species + "s";
	}

	private static boolean usesIndividualWording(String npcName)
	{
		if (BossRegistry.isBoss(npcName) || npcName.startsWith("The ") || npcName.indexOf(',') >= 0)
			return true;
		for (int i = 1; i < npcName.length(); i++)
		{
			if (Character.isUpperCase(npcName.charAt(i))) return true;
		}
		return false;
	}

	private static String individualMessage(String npcName, int style)
	{
		String embeddedName = npcName.startsWith("The ")
			? "the " + npcName.substring(4) : npcName;
		switch (Math.floorMod(style, 3))
		{
			case 0:
				return npcName + " has left this world for good.";
			case 1:
				return "You have slain " + embeddedName
					+ " for the final time. This foe is gone forever.";
			default:
				return "With that final blow, " + embeddedName
					+ " has vanished from Gielinor forever.";
		}
	}

	private static Map<String, String> irregularPlurals()
	{
		Map<String, String> plurals = new HashMap<>();
		plurals.put("man", "men");
		plurals.put("woman", "women");
		plurals.put("child", "children");
		plurals.put("person", "people");
		plurals.put("mouse", "mice");
		plurals.put("goose", "geese");
		plurals.put("ox", "oxen");
		plurals.put("sheep", "sheep");
		plurals.put("deer", "deer");
		plurals.put("fish", "fish");
		plurals.put("cyclops", "cyclopes");
		plurals.put("thief", "thieves");
		plurals.put("wolf", "wolves");
		plurals.put("dwarf", "dwarves");
		return plurals;
	}

	private static String capitalize(String text)
	{
		return text.isEmpty() ? text : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}
}

package com.extinctionman;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import javax.imageio.ImageIO;

final class ExtinctionLogIcon
{
	private ExtinctionLogIcon()
	{
	}

	static BufferedImage create()
	{
		try (InputStream stream = ExtinctionLogIcon.class.getResourceAsStream("extinction-sigil.png"))
		{
			if (stream == null)
			{
				throw new IllegalStateException("Missing Extinction Sigil resource");
			}
			return ImageIO.read(stream);
		}
		catch (IOException ex)
		{
			throw new IllegalStateException("Unable to load Extinction Sigil", ex);
		}
	}
}

