final class ForbiddenLootOverlay extends Overlay
{
	private static final Color FORBIDDEN_TEXT = new Color(135, 138, 145);
	private final Client client;
	private final ForbiddenLootTracker tracker;

	@Inject
	ForbiddenLootOverlay(Client client, ForbiddenLootTracker tracker)
	{
		this.client = client;
		this.tracker = tracker;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		for (ForbiddenLootMarker marker : tracker.active(client.getTickCount()))
		{
			LocalPoint localPoint = LocalPoint.fromWorld(client, marker.getWorldPoint());
			if (localPoint == null)
			{
				continue;
			}

			int offset = 25;
			for (String itemName : marker.getItemNames())
			{
				String label = lockedLabel(itemName);
				Point textLocation = Perspective.getCanvasTextLocation(
					client, graphics, localPoint, label, offset);
				if (textLocation != null)
				{
					OverlayUtil.renderTextLocation(graphics, textLocation, label, FORBIDDEN_TEXT);
				}
				offset += 14;
			}
		}
		return null;
	}

	static String lockedLabel(String itemName)
	{
		return itemName + " (Locked)";
	}
}

package com.extinctionman;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;

@Singleton
final class ForbiddenLootTracker
{
	static final int LIFETIME_TICKS = 200;
	private final List<ForbiddenLootMarker> markers = new ArrayList<>();

	void add(WorldPoint worldPoint, int itemId, String itemName, int currentTick)
	{
		if (worldPoint == null)
		{
			return;
		}
		for (ForbiddenLootMarker marker : markers)
		{
			if (marker.getWorldPoint().equals(worldPoint))
			{
				marker.refresh(itemId, itemName, currentTick + LIFETIME_TICKS);
				return;
			}
		}
		markers.add(new ForbiddenLootMarker(worldPoint, itemId, itemName,
			currentTick + LIFETIME_TICKS));
	}

	boolean isForbidden(WorldPoint worldPoint, int itemId, int currentTick)
	{
		return active(currentTick).stream()
			.anyMatch(marker -> marker.getWorldPoint().equals(worldPoint) && marker.containsItem(itemId));
	}

	void remove(WorldPoint worldPoint, int itemId)
	{
		if (worldPoint == null) return;
		for (ForbiddenLootMarker marker : markers)
		{
			if (marker.getWorldPoint().equals(worldPoint)) marker.removeItem(itemId);
		}
		markers.removeIf(ForbiddenLootMarker::isEmpty);
	}

	List<ForbiddenLootMarker> active(int currentTick)
	{
		markers.removeIf(marker -> marker.isExpired(currentTick));
		return new ArrayList<>(markers);
	}

	void clear()
	{
		markers.clear();
	}
}

package com.extinctionman;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

final class FullBackupCodec
{
	private static final String HEADER = "EXTINCTION-MAN-BACKUP-V3";
	private FullBackupCodec() {}

	static String encode(String soulStorage, String metaStorage)
	{
		return HEADER + "\nSOULS=" + encodeText(soulStorage) + "\nMETA=" + encodeText(metaStorage);
	}

	static Decoded decode(String backup)
	{
		if (backup == null || !backup.startsWith(HEADER + "\n"))
		{
			throw new IllegalArgumentException("This is not a current Extinction Man backup.");
		}
		String[] lines = backup.split("\\n");
		if (lines.length != 3 || !lines[1].startsWith("SOULS=") || !lines[2].startsWith("META="))
		{
			throw new IllegalArgumentException("The Extinction Man backup is damaged.");
		}
		try
		{
			String souls = decodeText(lines[1].substring("SOULS=".length()));
			String meta = decodeText(lines[2].substring("META=".length()));
			SoulLogCodec.decodeStorage(souls);
			MetaProgressCodec.decode(meta);
			return new Decoded(souls, meta);
		}
		catch (RuntimeException ex)
		{
			throw new IllegalArgumentException("The Extinction Man backup is damaged.", ex);
		}
	}

	private static String encodeText(String value)
	{
		return Base64.getEncoder().encodeToString(value.getBytes(StandardCharsets.UTF_8));
	}

	private static String decodeText(String value)
	{
		return new String(Base64.getDecoder().decode(value), StandardCharsets.UTF_8);
	}

	static final class Decoded
	{
		private final String soulStorage;
		private final String metaStorage;
		Decoded(String soulStorage, String metaStorage)
		{
			this.soulStorage = soulStorage;
			this.metaStorage = metaStorage;
		}
		String getSoulStorage() { return soulStorage; }
		String getMetaStorage() { return metaStorage; }
	}
}

