final class KillCreditTracker<T>
{
	enum DeathClaim
	{
		CREDITED,
		CONTESTED,
		NOT_OURS
	}

	private final Map<T, Integer> lastOwnDamage = new IdentityHashMap<>();
	private final Set<T> contestedTargets = Collections.newSetFromMap(new IdentityHashMap<>());

	void markOwnDamage(T target, int tick)
	{
		lastOwnDamage.put(target, tick);
	}

	void markOtherDamage(T target)
	{
		contestedTargets.add(target);
	}

	DeathClaim claimDeath(T target, int tick)
	{
		return claimDeath(target, tick, false);
	}

	DeathClaim claimDeath(T target, int tick, boolean allowSharedCredit)
	{
		Integer damageTick = lastOwnDamage.remove(target);
		boolean contested = contestedTargets.remove(target);
		if (damageTick == null)
		{
			return DeathClaim.NOT_OURS;
		}
		return contested && !allowSharedCredit ? DeathClaim.CONTESTED : DeathClaim.CREDITED;
	}

	void forget(T target)
	{
		lastOwnDamage.remove(target);
		contestedTargets.remove(target);
	}

	void clear()
	{
		lastOwnDamage.clear();
		contestedTargets.clear();
	}
}

package com.extinctionman;

final class MandatoryExceptionMatcher
{
	private MandatoryExceptionMatcher()
	{
	}

	static boolean matches(boolean enabled, String configuredNpc, String exactNpcName)
	{
		return enabled
			&& configuredNpc != null
			&& exactNpcName != null
			&& !configuredNpc.trim().isEmpty()
			&& exactNpcName.equalsIgnoreCase(configuredNpc.trim());
	}
}

package com.extinctionman;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

final class MetaProgressCodec
{
	private static final String HEADER_V1 = "EM-META-1";
	private static final String HEADER_V2 = "EM-META-2";
	private static final String HEADER_V3 = "EM-META-3";
	private static final String HEADER_V4 = "EM-META-4";
	private static final String HEADER_V5 = "EM-META-5";
	private static final String HEADER_V6 = "EM-META-6";

	private MetaProgressCodec() {}

	static String encode(Set<String> rewardedSpecies, List<WhitelistUnlock> unlocks)
	{
		return encode(rewardedSpecies, unlocks, 0);
	}

	static String encode(Set<String> rewardedSpecies, List<WhitelistUnlock> unlocks,
		int forfeitedPoints)
	{
		return encode(rewardedSpecies, unlocks, forfeitedPoints, 0);
	}

	static String encode(Set<String> rewardedSpecies, List<WhitelistUnlock> unlocks,
		int forfeitedPoints, int bonusPoints)
	{
		return encode(rewardedSpecies, unlocks, forfeitedPoints, bonusPoints,
			Collections.<SoulPermit>emptyList());
	}

	static String encode(Set<String> rewardedSpecies, List<WhitelistUnlock> unlocks,
		int forfeitedPoints, int bonusPoints, SoulPermit activePermit)
	{
		return encode(rewardedSpecies, unlocks, forfeitedPoints, bonusPoints,
			activePermit == null ? Collections.emptyList() : Collections.singletonList(activePermit));
	}

	static String encode(Set<String> rewardedSpecies, List<WhitelistUnlock> unlocks,
		int forfeitedPoints, int bonusPoints, List<SoulPermit> activePermits)
	{
		StringBuilder text = new StringBuilder(HEADER_V6)
			.append("\nF|").append(Math.max(0, forfeitedPoints));
		text.append("\nB|").append(bonusPoints);
		for (SoulPermit permit : activePermits)
		{
			text.append("\nP|").append(permit.isBoss() ? '1' : '0')
				.append('|').append(permit.getRemainingKills())
				.append('|').append(encodeText(permit.getSourceName()));
		}
		rewardedSpecies.stream().sorted(String.CASE_INSENSITIVE_ORDER)
			.forEach(name -> text.append("\nR|").append(encodeText(name)));
		for (WhitelistUnlock unlock : unlocks)
		{
			text.append("\nW|").append(unlock.getItemId())
				.append('|').append(encodeText(unlock.getItemName()))
				.append('|').append(encodeText(unlock.getSourceNpcName()))
				.append('|').append(unlock.isAcquired() ? '1' : '0');
			text.append('|').append(unlock.getPointCost());
		}
		return text.toString();
	}

	static Decoded decode(String text)
	{
		String header = text == null ? "" : text.split("\\n", 2)[0];
		if (!HEADER_V1.equals(header) && !HEADER_V2.equals(header)
			&& !HEADER_V3.equals(header) && !HEADER_V4.equals(header)
			&& !HEADER_V5.equals(header) && !HEADER_V6.equals(header))
		{
			throw new IllegalArgumentException("Unsupported Soul Energy data version.");
		}
		Set<String> rewarded = new HashSet<>();
		List<WhitelistUnlock> unlocks = new ArrayList<>();
		int forfeitedPoints = 0;
		int bonusPoints = 0;
		List<SoulPermit> activePermits = new ArrayList<>();
		boolean legacyEconomy = !HEADER_V5.equals(header) && !HEADER_V6.equals(header);
		String[] lines = text.split("\\n");
		try
		{
			for (int index = 1; index < lines.length; index++)
			{
				String[] parts = lines[index].split("\\|", -1);
				if (parts.length == 2 && "F".equals(parts[0]))
				{
					forfeitedPoints = Math.max(0, Integer.parseInt(parts[1]));
				}
				else if (parts.length == 2 && "B".equals(parts[0])
					&& (HEADER_V4.equals(header) || HEADER_V5.equals(header) || HEADER_V6.equals(header)))
				{
					bonusPoints = Integer.parseInt(parts[1]);
				}
				else if (parts.length == 3 && "P".equals(parts[0]) && HEADER_V5.equals(header))
				{
					activePermits.add(new SoulPermit(decodeText(parts[2]), "1".equals(parts[1])));
				}
				else if (parts.length == 4 && "P".equals(parts[0]) && HEADER_V6.equals(header))
				{
					activePermits.add(new SoulPermit(decodeText(parts[3]), "1".equals(parts[1]),
						Integer.parseInt(parts[2])));
				}
				else if (parts.length == 2 && "R".equals(parts[0]))
				{
					rewarded.add(decodeText(parts[1]));
				}
				else if (parts.length == (HEADER_V3.equals(header) || HEADER_V4.equals(header)
					|| HEADER_V5.equals(header) || HEADER_V6.equals(header) ? 6 : 5)
					&& "W".equals(parts[0]))
				{
					unlocks.add(new WhitelistUnlock(Integer.parseInt(parts[1]),
						decodeText(parts[2]), decodeText(parts[3]), "1".equals(parts[4]),
						HEADER_V3.equals(header) || HEADER_V4.equals(header) || HEADER_V5.equals(header)
							|| HEADER_V6.equals(header)
							? Integer.parseInt(parts[5]) : 1));
				}
				else
				{
					throw new IllegalArgumentException();
				}
			}
		}
		catch (RuntimeException ex)
		{
			throw new IllegalArgumentException("The Soul Energy data is damaged.", ex);
		}
		if (legacyEconomy)
		{
			List<WhitelistUnlock> migrated = new ArrayList<>();
			for (WhitelistUnlock unlock : unlocks)
			{
				migrated.add(new WhitelistUnlock(unlock.getItemId(), unlock.getItemName(),
					unlock.getSourceNpcName(), unlock.isAcquired(), unlock.getPointCost() * 100));
			}
			unlocks = migrated;
			forfeitedPoints *= 100;
			bonusPoints *= 100;
		}
		return new Decoded(rewarded, unlocks, forfeitedPoints, bonusPoints, activePermits,
			legacyEconomy);
	}

	private static String encodeText(String value)
	{
		return Base64.getUrlEncoder().withoutPadding()
			.encodeToString(value.getBytes(StandardCharsets.UTF_8));
	}

	private static String decodeText(String value)
	{
		return new String(Base64.getUrlDecoder().decode(value), StandardCharsets.UTF_8);
	}

	static final class Decoded
	{
		private final Set<String> rewardedSpecies;
		private final List<WhitelistUnlock> unlocks;
		private final int forfeitedPoints;
		private final int bonusPoints;
		private final List<SoulPermit> activePermits;
		private final boolean legacyEconomy;

		Decoded(Set<String> rewardedSpecies, List<WhitelistUnlock> unlocks,
			int forfeitedPoints, int bonusPoints, List<SoulPermit> activePermits, boolean legacyEconomy)
		{
			this.rewardedSpecies = rewardedSpecies;
			this.unlocks = unlocks;
			this.forfeitedPoints = forfeitedPoints;
			this.bonusPoints = bonusPoints;
			this.activePermits = activePermits;
			this.legacyEconomy = legacyEconomy;
		}

		Set<String> getRewardedSpecies() { return rewardedSpecies; }
		List<WhitelistUnlock> getUnlocks() { return unlocks; }
		int getForfeitedPoints() { return forfeitedPoints; }
		int getBonusPoints() { return bonusPoints; }
		SoulPermit getActivePermit() { return activePermits.isEmpty() ? null : activePermits.get(0); }
		List<SoulPermit> getActivePermits() { return new ArrayList<>(activePermits); }
		boolean isLegacyEconomy() { return legacyEconomy; }
	}
}

package com.extinctionman;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
final class MetaProgressRepository
{
	static final int SOUL_ITEM_COST = 100;
	private static final String PROFILE_KEY = "soulPointsMetaV1";
	private static final String LEGACY_RECOVERY_KEY = "unsyncedSoulPointsMetaV1";
	private static final String RECOVERY_KEY_PREFIX = "unsyncedSoulPointsMetaV1_";
	private final ConfigManager configManager;
	private final Set<String> rewardedSpecies = new HashSet<>();
	private final List<WhitelistUnlock> unlocks = new ArrayList<>();
	private int forfeitedPoints;
	private int bonusPoints;
	private final List<SoulPermit> activePermits = new ArrayList<>();
	private boolean loaded;
	private boolean initialReconciliationNeeded;

	@Inject
	MetaProgressRepository(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	synchronized SoulPointAward award(String exactNpcName)
	{
		ensureLoaded();
		int pointsBefore = SoulPointEconomy.earnedEnergy(rewardedSpecies);
		if (!rewardedSpecies.add(exactNpcName))
		{
			return new SoulPointAward(false, 0);
		}
		save();
		int pointsAfter = SoulPointEconomy.earnedEnergy(rewardedSpecies);
		return new SoulPointAward(true, pointsAfter - pointsBefore);
	}

	synchronized boolean revokeAward(String exactNpcName)
	{
		ensureLoaded();
		if (!rewardedSpecies.remove(exactNpcName))
		{
			return false;
		}
		save();
		return true;
	}

	synchronized int getCompletedExterminations()
	{
		ensureLoaded();
		return rewardedSpecies.size();
	}

	synchronized int getAvailablePoints()
	{
		ensureLoaded();
		int spent = unlocks.stream().mapToInt(WhitelistUnlock::getPointCost).sum() + forfeitedPoints;
		return Math.max(0, SoulPointEconomy.earnedEnergy(rewardedSpecies) + bonusPoints - spent);
	}

	synchronized int getSpentPoints()
	{
		ensureLoaded();
		return unlocks.stream().mapToInt(WhitelistUnlock::getPointCost).sum() + forfeitedPoints;
	}

	synchronized boolean canCreateUnlock()
	{
		return getAvailablePoints() >= getNewUnlockCost();
	}

	int getNewUnlockCost()
	{
		return SOUL_ITEM_COST;
	}

	synchronized SoulPermit getActivePermit()
	{
		ensureLoaded();
		return activePermits.isEmpty() ? null : activePermits.get(0);
	}

	synchronized List<SoulPermit> getActivePermits()
	{
		ensureLoaded();
		return new ArrayList<>(activePermits);
	}

	synchronized SoulPermit findActivePermit(String sourceName)
	{
		ensureLoaded();
		return activePermits.stream().filter(permit -> permit.matches(sourceName))
			.findFirst().orElse(null);
	}

	synchronized boolean canCreatePermit(boolean boss, int kills)
	{
		if (kills < 1) return false;
		return getAvailablePoints() >= (boss ? 10 : 1) * kills;
	}

	synchronized boolean canCreatePermit(boolean boss)
	{
		return canCreatePermit(boss, 1);
	}

	synchronized void createPermit(String sourceName, boolean boss, int kills)
	{
		if (!canCreatePermit(boss, kills)) throw new IllegalStateException("Not enough Soul Energy.");
		SoulPermit created = new SoulPermit(sourceName, boss, kills);
		for (int i = 0; i < activePermits.size(); i++)
		{
			SoulPermit existing = activePermits.get(i);
			if (existing.matches(sourceName) && existing.isBoss() == boss)
			{
				activePermits.set(i, existing.addKills(kills));
				forfeitedPoints += created.getPointCost();
				save();
				return;
			}
		}
		activePermits.add(created);
		forfeitedPoints += created.getPointCost();
		save();
	}

	synchronized void createPermit(String sourceName, boolean boss)
	{
		createPermit(sourceName, boss, 1);
	}

	synchronized boolean consumePermit(String sourceName)
	{
		ensureLoaded();
		for (int i = 0; i < activePermits.size(); i++)
		{
			SoulPermit permit = activePermits.get(i);
			if (!permit.matches(sourceName)) continue;
			SoulPermit remaining = permit.consumeOne();
			if (remaining == null) activePermits.remove(i);
			else activePermits.set(i, remaining);
			save();
			return true;
		}
		return false;
	}

	synchronized void createUnlock(int itemId, String itemName, String sourceNpcName)
	{
		if (!canCreateUnlock())
		{
			throw new IllegalStateException("Not enough Soul Energy for an Unbound Soul.");
		}
		unlocks.add(new WhitelistUnlock(itemId, itemName, sourceNpcName, false, getNewUnlockCost()));
		save();
	}

	synchronized WhitelistUnlock getActiveHunt()
	{
		ensureLoaded();
		return unlocks.stream().filter(unlock -> !unlock.isAcquired()).findFirst().orElse(null);
	}

	synchronized List<WhitelistUnlock> getActiveHunts()
	{
		ensureLoaded();
		List<WhitelistUnlock> active = new ArrayList<>();
		for (WhitelistUnlock unlock : unlocks)
		{
			if (!unlock.isAcquired()) active.add(unlock);
		}
		return active;
	}

	synchronized boolean completeActiveHunt()
	{
		WhitelistUnlock active = getActiveHunt();
		if (active == null)
		{
			return false;
		}
		int index = unlocks.indexOf(active);
		unlocks.set(index, active.acquired());
		save();
		return true;
	}

	synchronized boolean isWhitelisted(int canonicalItemId)
	{
		ensureLoaded();
		return unlocks.stream().anyMatch(unlock -> unlock.getItemId() == canonicalItemId);
	}

	synchronized boolean isWhitelisted(int canonicalItemId, String itemName)
	{
		ensureLoaded();
		return unlocks.stream().anyMatch(unlock -> unlock.matchesItem(canonicalItemId, itemName));
	}

	synchronized List<WhitelistUnlock> getUnlocks()
	{
		ensureLoaded();
		return new ArrayList<>(unlocks);
	}

	synchronized boolean removeUnlock(int canonicalItemId, boolean refundPoint)
	{
		ensureLoaded();
		int index = -1;
		for (int i = 0; i < unlocks.size(); i++)
		{
			if (unlocks.get(i).getItemId() == canonicalItemId)
			{
				index = i;
				break;
			}
		}
		if (index < 0) return false;
		WhitelistUnlock removed = unlocks.remove(index);
		if (!refundPoint)
		{
			forfeitedPoints += removed.getPointCost();
		}
		save();
		return true;
	}

	synchronized Set<String> getRewardedSpecies()
	{
		ensureLoaded();
		return new HashSet<>(rewardedSpecies);
	}

	synchronized void resetSoulPointProgress()
	{
		ensureLoaded();
		rewardedSpecies.clear();
		bonusPoints = 0;
		activePermits.clear();
		save();
	}

	synchronized boolean removeUnlock(WhitelistUnlock unlock, boolean refundEnergy)
	{
		ensureLoaded();
		int index = unlocks.indexOf(unlock);
		if (index < 0) return false;
		WhitelistUnlock removed = unlocks.remove(index);
		if (!refundEnergy) forfeitedPoints += removed.getPointCost();
		save();
		return true;
	}

	synchronized boolean completeHunt(WhitelistUnlock active)
	{
		ensureLoaded();
		if (active == null || active.isAcquired()) return false;
		int index = unlocks.indexOf(active);
		if (index < 0) return false;
		unlocks.set(index, active.acquired());
		save();
		return true;
	}

	synchronized void grantBonusSoulPoint()
	{
		grantBonusSoulPoints(1);
	}

	synchronized void grantBonusSoulPoints(int amount)
	{
		ensureLoaded();
		bonusPoints += Math.max(0, amount);
		save();
	}

	synchronized void setAvailableSoulEnergy(int amount)
	{
		ensureLoaded();
		if (amount < 0) throw new IllegalArgumentException("Soul Energy cannot be negative.");
		int spent = unlocks.stream().mapToInt(WhitelistUnlock::getPointCost).sum() + forfeitedPoints;
		bonusPoints = amount + spent - SoulPointEconomy.earnedEnergy(rewardedSpecies);
		save();
	}

	synchronized void resetAllProgress()
	{
		ensureLoaded();
		rewardedSpecies.clear();
		unlocks.clear();
		forfeitedPoints = 0;
		bonusPoints = 0;
		activePermits.clear();
		initialReconciliationNeeded = false;
		save();
	}

	synchronized boolean needsInitialReconciliation()
	{
		ensureLoaded();
		return initialReconciliationNeeded;
	}

	synchronized void completeInitialReconciliation(Set<String> completedSpecies)
	{
		ensureLoaded();
		if (!initialReconciliationNeeded) return;
		rewardedSpecies.addAll(completedSpecies);
		initialReconciliationNeeded = false;
		save();
	}

	synchronized boolean synchronizeExtinctionAwards(Set<String> completedSpecies)
	{
		ensureLoaded();
		Set<String> expected = completedSpecies == null
			? java.util.Collections.emptySet() : new HashSet<>(completedSpecies);
		if (!initialReconciliationNeeded && rewardedSpecies.equals(expected))
		{
			return false;
		}
		rewardedSpecies.clear();
		rewardedSpecies.addAll(expected);
		initialReconciliationNeeded = false;
		save();
		return true;
	}

	synchronized String exportData()
	{
		ensureLoaded();
		return MetaProgressCodec.encode(rewardedSpecies, unlocks, forfeitedPoints, bonusPoints, activePermits);
	}

	synchronized void importData(String data)
	{
		MetaProgressCodec.Decoded decoded = MetaProgressCodec.decode(data);
		rewardedSpecies.clear();
		rewardedSpecies.addAll(decoded.getRewardedSpecies());
		unlocks.clear();
		unlocks.addAll(decoded.getUnlocks());
		forfeitedPoints = decoded.getForfeitedPoints();
		bonusPoints = decoded.getBonusPoints();
		activePermits.clear();
		activePermits.addAll(decoded.getActivePermits());
		loaded = true;
		initialReconciliationNeeded = false;
		save();
	}

	synchronized void reloadProfile()
	{
		loaded = false;
		rewardedSpecies.clear();
		unlocks.clear();
		forfeitedPoints = 0;
		bonusPoints = 0;
		activePermits.clear();
		initialReconciliationNeeded = false;
		ensureLoaded();
	}

	private void ensureLoaded()
	{
		if (loaded) return;
		loaded = true;
		String stored = configManager.getRSProfileConfiguration(ExtinctionManConfig.GROUP, PROFILE_KEY);
		String recovery = readRecovery();
		String source = StorageRecoveryPolicy.newestSnapshot(stored, recovery);
		initialReconciliationNeeded = source == null;
		boolean migratedEconomy = false;
		if (source != null)
		{
			MetaProgressCodec.Decoded decoded = MetaProgressCodec.decode(source);
			migratedEconomy = decoded.isLegacyEconomy();
			rewardedSpecies.addAll(decoded.getRewardedSpecies());
			unlocks.addAll(decoded.getUnlocks());
			forfeitedPoints = decoded.getForfeitedPoints();
			bonusPoints = decoded.getBonusPoints();
			activePermits.addAll(decoded.getActivePermits());
		}
		if (recovery != null || stored == null || migratedEconomy) save();
	}

	private void save()
	{
		String encoded = MetaProgressCodec.encode(rewardedSpecies, unlocks, forfeitedPoints, bonusPoints, activePermits);
		configManager.setConfiguration(ExtinctionManConfig.GROUP, recoveryKey(), encoded);
		configManager.setRSProfileConfiguration(ExtinctionManConfig.GROUP, PROFILE_KEY, encoded);
		String verification = configManager.getRSProfileConfiguration(
			ExtinctionManConfig.GROUP, PROFILE_KEY);
		if (StorageRecoveryPolicy.writeWasVerified(encoded, verification))
		{
			clearRecovery();
		}
	}

	private String readRecovery()
	{
		String recovery = configManager.getConfiguration(ExtinctionManConfig.GROUP, recoveryKey());
		return recovery != null ? recovery : configManager.getConfiguration(
			ExtinctionManConfig.GROUP, LEGACY_RECOVERY_KEY);
	}

	private void clearRecovery()
	{
		configManager.unsetConfiguration(ExtinctionManConfig.GROUP, recoveryKey());
		configManager.unsetConfiguration(ExtinctionManConfig.GROUP, LEGACY_RECOVERY_KEY);
	}

	private String recoveryKey()
	{
		String profileKey = configManager.getRSProfileKey();
		String identity = profileKey == null ? "unbound" : Base64.getUrlEncoder().withoutPadding()
			.encodeToString(profileKey.getBytes(StandardCharsets.UTF_8));
		return RECOVERY_KEY_PREFIX + identity;
	}
}

package com.extinctionman;

import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

@Slf4j
@Singleton
final class MilestoneAudio
{
	private final AudioPlayer player;
	private final ScheduledExecutorService executor;
	private final ExtinctionManConfig config;
	private volatile long generation;

	@Inject
	MilestoneAudio(AudioPlayer player, ScheduledExecutorService executor, ExtinctionManConfig config)
	{
		this.player = player;
		this.executor = executor;
		this.config = config;
	}

	void update(ExtinctionCelebration extinction, SoulItemFound item)
	{
		if (extinction != null && extinction.claimSound()) play("slayer-level-up.wav");
		if (item != null && item.claimSound()) play("prayer-level-up.wav");
	}

	private void play(String resource)
	{
		int volume = Math.max(0, Math.min(100, config.milestoneVolume()));
		if (!config.playMilestoneSounds() || volume == 0) return;
		long currentGeneration = generation;
		float gain = (float) (20 * Math.log10(volume / 100.0));
		executor.execute(() ->
		{
			if (currentGeneration != generation) return;
			try { player.play(MilestoneAudio.class, resource, gain); }
			catch (Exception e) { log.warn("Unable to play milestone audio {}", resource, e); }
		});
	}

	void clear()
	{
		generation++;
	}
}

package com.extinctionman;

import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Collection;
import java.util.Set;
import java.util.TreeSet;

final class MonsterCatalogCodec
{
	private MonsterCatalogCodec() {}

	static String encode(Collection<String> names)
	{
		StringBuilder encoded = new StringBuilder();
		for (String name : new TreeSet<>(names))
		{
			if (encoded.length() > 0) encoded.append(',');
			encoded.append(Base64.getUrlEncoder().withoutPadding()
				.encodeToString(name.getBytes(StandardCharsets.UTF_8)));
		}
		return encoded.toString();
	}

	static Set<String> decode(String encoded)
	{
		Set<String> names = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		if (encoded == null || encoded.trim().isEmpty()) return names;
		for (String part : encoded.split(","))
		{
			try
			{
				names.add(new String(Base64.getUrlDecoder().decode(part), StandardCharsets.UTF_8));
			}
			catch (IllegalArgumentException ignored)
			{
				// Ignore one damaged catalogue entry instead of losing the complete catalogue.
			}
		}
		return names;
	}
}

