import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import java.awt.Polygon;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

final class WhitelistLootOverlay extends Overlay
{
	private static final Color BEAM = new Color(255, 178, 25);
	private final Client client;
	private final WhitelistLootTracker tracker;

	@Inject
	WhitelistLootOverlay(Client client, WhitelistLootTracker tracker)
	{
		this.client = client;
		this.tracker = tracker;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		long now = System.currentTimeMillis();
		float pulse = (float) ((Math.sin(now / 210.0) + 1.0) * 0.5);
		Paint oldPaint = graphics.getPaint();
		Stroke oldStroke = graphics.getStroke();
		Composite oldComposite = graphics.getComposite();
		Object oldAntialiasing = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
			RenderingHints.VALUE_ANTIALIAS_ON);
		for (WhitelistLootMarker marker : tracker.active(client.getTickCount()))
		{
			LocalPoint localPoint = LocalPoint.fromWorld(client, marker.getWorldPoint());
			if (localPoint == null) continue;
			Polygon tile = Perspective.getCanvasTilePoly(client, localPoint);
			Point base = Perspective.localToCanvas(client, localPoint,
				client.getTopLevelWorldView().getPlane());
			if (tile == null || base == null) continue;

			int x = base.getX();
			int bottom = base.getY();
			int height = 145 + Math.round(8 * pulse);
			int top = bottom - height;

			graphics.setColor(new Color(255, 178, 25, 24 + Math.round(22 * pulse)));
			graphics.fillPolygon(tile);
			graphics.setColor(new Color(255, 205, 75, 55 + Math.round(45 * pulse)));
			graphics.setStroke(new BasicStroke(4.5f + pulse * 2f,
				BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			graphics.drawPolygon(tile);

			graphics.setPaint(new RadialGradientPaint(x, bottom - 3, 34 + 7 * pulse,
				new float[]{0f, .38f, 1f},
				new Color[]{new Color(255, 255, 235, 165),
					new Color(255, 190, 45, 75), new Color(210, 105, 0, 0)}));
			graphics.fillOval(x - 42, bottom - 45, 84, 84);

			graphics.setPaint(new GradientPaint(x, top,
				new Color(255, 220, 90, 0), x, bottom,
				new Color(255, 178, 25, 80 + Math.round(45 * pulse))));
			graphics.fillRoundRect(x - 17, top, 34, height, 24, 24);
			graphics.setPaint(new GradientPaint(x, top,
				new Color(255, 255, 235, 8), x, bottom,
				new Color(255, 245, 180, 175 + Math.round(55 * pulse))));
			graphics.fillRoundRect(x - 7, top + 4, 14, height - 4, 12, 12);

			int moteY = bottom - 28 - (int) ((now / 18 + marker.getItemId()) % 105);
			graphics.setColor(new Color(255, 238, 135, 130 + Math.round(90 * pulse)));
			graphics.fillOval(x - 14, moteY, 5, 5);
			graphics.fillOval(x + 10, moteY + 31, 4, 4);
			Point text = Perspective.getCanvasTextLocation(client, graphics, localPoint,
				"Soul item: " + marker.getItemName(), height + 10);
			if (text != null)
			{
				OverlayUtil.renderTextLocation(graphics, text,
					"Soul item: " + marker.getItemName(), BEAM);
			}
		}
		graphics.setPaint(oldPaint);
		graphics.setStroke(oldStroke);
		graphics.setComposite(oldComposite);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAntialiasing);
		return null;
	}
}

package com.extinctionman;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;

@Singleton
final class WhitelistLootTracker
{
	static final int LIFETIME_TICKS = 300;
	private final List<WhitelistLootMarker> markers = new ArrayList<>();

	synchronized void add(WorldPoint worldPoint, int itemId, String itemName, int currentTick)
	{
		add(worldPoint, itemId, itemName, null, currentTick);
	}

	synchronized void add(WorldPoint worldPoint, int itemId, String itemName, String sourceName,
		int currentTick)
	{
		if (worldPoint == null) return;
		markers.removeIf(marker -> marker.getWorldPoint().equals(worldPoint)
			&& marker.getItemId() == itemId);
		markers.add(new WhitelistLootMarker(worldPoint, itemId, itemName, sourceName,
			currentTick + LIFETIME_TICKS));
	}

	synchronized List<WhitelistLootMarker> active(int currentTick)
	{
		markers.removeIf(marker -> marker.isExpired(currentTick));
		return new ArrayList<>(markers);
	}

	synchronized boolean contains(WorldPoint worldPoint, int itemId, int currentTick)
	{
		return active(currentTick).stream().anyMatch(marker -> marker.getWorldPoint().equals(worldPoint)
			&& marker.getItemId() == itemId);
	}

	synchronized String sourceAt(WorldPoint worldPoint, int itemId, int currentTick)
	{
		for (WhitelistLootMarker marker : active(currentTick))
		{
			if (marker.getWorldPoint().equals(worldPoint) && marker.getItemId() == itemId)
				return marker.getSourceName();
		}
		return null;
	}

	synchronized void remove(WorldPoint worldPoint, int itemId)
	{
		if (worldPoint == null) return;
		markers.removeIf(marker -> marker.getWorldPoint().equals(worldPoint)
			&& marker.getItemId() == itemId);
	}

	synchronized List<WhitelistLootMarker> drain(int currentTick)
	{
		List<WhitelistLootMarker> remaining = active(currentTick);
		markers.clear();
		return remaining;
	}

	synchronized List<WhitelistLootMarker> drainMatching(String sourceName, int itemId,
		int currentTick)
	{
		List<WhitelistLootMarker> matches = new ArrayList<>();
		for (WhitelistLootMarker marker : active(currentTick))
		{
			if (marker.getItemId() == itemId && java.util.Objects.equals(sourceName,
				marker.getSourceName())) matches.add(marker);
		}
		markers.removeAll(matches);
		return matches;
	}

	synchronized void clear()
	{
		markers.clear();
	}
}

