		set(plugin, "pendingWaveNpc", victim);
		set(plugin, "pendingWaveNpcName", "Goblin");
		set(plugin, "pendingWavePermit", true);
		Method ghost = ExtinctionManPlugin.class.getDeclaredMethod("isExtinctGhost", NPC.class);
